/**
 * Returns a biomechanically accurate GIF URL for an exercise.
 * If usedGifs is provided, it strictly guarantees that no duplicated GIF
 * will ever be returned for this workout or context session.
 */
export function getAccurateExerciseGif(
  name: string,
  category: string = "",
  usedGifs?: Set<string>
): string {
  if (!name) {
    return getCategoryAlternative(category, usedGifs);
  }

  // Strip file extensions (.gif, .mp4, etc.), 'exercise-' prefixes, and special characters
  const clean = name
    .toLowerCase()
    .replace(/\.(gif|mp4|webm|png|jpe?g|webp|mov)$/i, "")
    .replace(/^exercise[-_\s]/i, "")
    .replace(/^exercise/i, "")
    .replace(/[^a-z0-9]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const normNoSpaces = clean.replace(/\s+/g, "");

  // Deterministic biological guarantee for Face Pulls and rear-delt pull aparts
  if (
    clean === "face pull" ||
    clean === "face pulls" ||
    clean === "facepull" ||
    clean === "facepulls" ||
    normNoSpaces === "facepull" ||
    normNoSpaces === "facepulls" ||
    clean.includes("face pull") ||
    clean.includes("facepull") ||
    clean.includes("rear delt row with rope") ||
    clean.includes("band pull apart")
  ) {
    return "https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0233-ZfyAGhK.gif";
  }

  // Deterministic biological guarantee for Pull Ups
  if (
    clean === "pull up" ||
    clean === "pull ups" ||
    clean === "pullup" ||
    clean === "pullups" ||
    clean === "pull ups chin ups" ||
    clean.startsWith("pull up") ||
    clean.startsWith("pull-up") ||
    clean.startsWith("pullup") ||
    clean === "weighted pull up" ||
    clean === "weighted pull-up" ||
    clean === "wide grip pull up" ||
    clean === "neutral grip pull ups"
  ) {
    return "https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0652-lBDjFxJ.gif";
  }

  // Deterministic biological guarantee for Chin Ups
  if (
    clean === "chin up" ||
    clean === "chin ups" ||
    clean === "chinup" ||
    clean === "chinups" ||
    clean.startsWith("chin up") ||
    clean.startsWith("chin-up")
  ) {
    return "https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1326-T2mxWqc.gif";
  }

  // Deterministic biological guarantee for Chest Dips / Dips
  if (
    clean === "chest dip" ||
    clean === "chest dips" ||
    clean === "chestdip" ||
    clean === "chestdips" ||
    clean === "dips" ||
    clean === "dip" ||
    clean.startsWith("chest dip") ||
    clean.startsWith("chest-dip") ||
    clean === "parallel bar dips" ||
    clean === "bar dips"
  ) {
    return "https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0251-9WTm7dq.gif";
  }

  // 1. Check exact key in the unique accurate map
  if (clean && ACCURATE_EXERCISE_MEDIA_MAP[clean]) {
    const candidate = ACCURATE_EXERCISE_MEDIA_MAP[clean];
    if (!usedGifs || !usedGifs.has(candidate)) {
      usedGifs?.add(candidate);
      return candidate;
    }
  }

  if (normNoSpaces && ACCURATE_EXERCISE_MEDIA_MAP[normNoSpaces]) {
    const candidate = ACCURATE_EXERCISE_MEDIA_MAP[normNoSpaces];
    if (!usedGifs || !usedGifs.has(candidate)) {
      usedGifs?.add(candidate);
      return candidate;
    }
  }

  // 2. Check if a partial or substring key exists in the unique map
  for (const [mapKey, gifUrl] of Object.entries(ACCURATE_EXERCISE_MEDIA_MAP)) {
    if (mapKey.length > 4) {
      const mapKeyNorm = mapKey.replace(/\s+/g, "");
      if (
        clean === mapKey ||
        normNoSpaces === mapKeyNorm ||
        clean.startsWith(mapKey + " ") ||
        mapKey.startsWith(clean + " ")
      ) {
        if (!usedGifs || !usedGifs.has(gifUrl)) {
          usedGifs?.add(gifUrl);
          return gifUrl;
        }
      }
    }
  }

  // 3. Fallback to unique pool item matching exercise name or category
  return getCategoryAlternative(clean + " " + (category || ""), usedGifs);
}

/**
 * Helper to retrieve a unique fallback GIF from category pools that hasn't been used yet
 */
function getCategoryAlternative(hint: string, usedGifs?: Set<string>): string {
  const hintLower = hint.toLowerCase();

  let targetPool = CATEGORY_FALLBACK_POOLS.core;
  if (hintLower.includes("chest") || hintLower.includes("press") || hintLower.includes("bench") || hintLower.includes("push")) {
    targetPool = CATEGORY_FALLBACK_POOLS.chest;
  } else if (hintLower.includes("back") || hintLower.includes("pull") || hintLower.includes("row") || hintLower.includes("lat")) {
    targetPool = CATEGORY_FALLBACK_POOLS.back;
  } else if (hintLower.includes("shoulder") || hintLower.includes("delt") || hintLower.includes("overhead")) {
    targetPool = CATEGORY_FALLBACK_POOLS.shoulders;
  } else if (hintLower.includes("bicep") || hintLower.includes("curl")) {
    targetPool = CATEGORY_FALLBACK_POOLS.biceps;
  } else if (hintLower.includes("tricep") || hintLower.includes("dip")) {
    targetPool = CATEGORY_FALLBACK_POOLS.triceps;
  } else if (hintLower.includes("glute") || hintLower.includes("thrust") || hintLower.includes("bridge")) {
    targetPool = CATEGORY_FALLBACK_POOLS.glutes;
  } else if (hintLower.includes("leg") || hintLower.includes("squat") || hintLower.includes("lunge") || hintLower.includes("quad") || hintLower.includes("calf")) {
    targetPool = CATEGORY_FALLBACK_POOLS.legs;
  } else if (hintLower.includes("cardio") || hintLower.includes("run") || hintLower.includes("jump") || hintLower.includes("burpee") || hintLower.includes("hiit")) {
    targetPool = CATEGORY_FALLBACK_POOLS.cardio;
  } else if (hintLower.includes("stretch") || hintLower.includes("mobility") || hintLower.includes("yoga") || hintLower.includes("cat") || hintLower.includes("flow")) {
    targetPool = CATEGORY_FALLBACK_POOLS.mobility;
  }

  if (targetPool && targetPool.length > 0) {
    if (usedGifs) {
      for (const url of targetPool) {
        if (!usedGifs.has(url)) {
          usedGifs.add(url);
          return url;
        }
      }
    } else {
      return targetPool[0];
    }
  }

  // Fallback to any unused GIF from any pool
  for (const pool of Object.values(CATEGORY_FALLBACK_POOLS)) {
    for (const url of pool) {
      if (!usedGifs || !usedGifs.has(url)) {
        usedGifs?.add(url);
        return url;
      }
    }
  }

  return "https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0662-I4hDWkc.gif";
}
